/* dsh-dabaitu — 一个包管三件事：左上角品牌 + 护眼暖黄纸质主题 + 标题栏「豆包」入口。
 *
 * 形态与宿主自带客户端插件一致：client.js 用 window.__ModuleLoader__.load 注册自己
 * （id 必须等于包名），工厂返回 { inject: ['slots', 'theme'], apply(ctx) }。
 *   'slots' —— 侧栏品牌槽位（sidebar.brand.mark / sidebar.brand.name，由
 *              @deepseek-ai/dsh-client-ui-sidebar 声明）与标题栏的会话操作列表
 *              （conversation.session.header.actions，由 ui-conversation 声明）；
 *   'theme' —— 宿主主题运行时（@deepseek-ai/dsh-client-ui-theme），ui-layout / 侧栏 /
 *              设置也都是通过 ctx.theme 取快照的。
 * 三段互不依赖：删掉 apply() 里对应的那一段，就只保留其余两件。
 *
 * 品牌部分：两个填充作为一组声明感知的注册（等声明出现才注册，声明消失一并撤回）；
 * 官方品牌填充由本包的 cordis.patch.yml 让位，卸载本包自动恢复官方鱼形标志与名称。
 *
 * 主题部分：宿主把界面上每一个颜色都写成 --dsw-static-* 色阶上的别名（bg-base、
 * border、label-*、sidebar、气泡、代码块……），所以只把两组中性色阶从冷灰蓝换成暖褐，
 * 整界面就一起跟着走。宿主这条色阶在浅色和深色规则里是同一套、从 00（最浅）到 1000
 * （最深）单调排列，深色模式取的是高段，因此两个 scheme 给同一个值：浅色是纸，深色
 * 自动是深色纸。品牌蓝与红/绿/琥珀语义色不动；只有当背景用的 deepseek-50/100/200
 * 三档浅色跟着纸走，并比页面底色略深，气泡仍可分辨。
 * 机制：ctx.theme.overrideTokens(source, tokens) —— 宿主注释里叫“slot shading 的
 * token 级对应物”，按来源分层、可撤销，source 由宿主强制写成本包 id。
 *
 * 纸纹：另装一个 <style>，照宿主自己那条叠加层的写法（fixed、pointer-events:none、
 * mix-blend-mode:multiply），把生成的无缝颗粒贴图乘到整个界面上。
 *
 * 「豆包」：标题行标题正后方多一个文字按钮，点它调 ctx.sidebarRight.openTab('browser',
 * { params: { url } })，也就是在应用内右侧的 Browser tab 里打开 doubao.com——不是系统
 * 浏览器。这两个服务用 ctx.get() 可选取用（宿主 ui-chat 也是这么做的），不在 inject 里
 * 声明：声明了就会在它们缺席时把整包挂起，纸纹与品牌跟着一起没了。
 */
const MARK_SRC =
  'data:image/png;base64,';

const NAME_TEXT = '大白兔白又白';

const DOUBAO_TEXT = '豆包';
const DOUBAO_URL = 'https://www.doubao.com/chat/';

const PAPER_GRAIN =
  'data:image/png;base64,';

const PAPER_TOKENS = {
  "--dsw-static-neutral-bluish-00": { light: "#f6efdd", dark: "#f6efdd" },
  "--dsw-static-neutral-bluish-50": { light: "#f2ead4", dark: "#f2ead4" },
  "--dsw-static-neutral-bluish-55": { light: "#efe6cf", dark: "#efe6cf" },
  "--dsw-static-neutral-bluish-60": { light: "#ede3cb", dark: "#ede3cb" },
  "--dsw-static-neutral-bluish-75": { light: "#e8ddc4", dark: "#e8ddc4" },
  "--dsw-static-neutral-bluish-90": { light: "#e4d8c0", dark: "#e4d8c0" },
  "--dsw-static-neutral-bluish-100": { light: "#e0d4bb", dark: "#e0d4bb" },
  "--dsw-static-neutral-bluish-150": { light: "#d9cdb2", dark: "#d9cdb2" },
  "--dsw-static-neutral-bluish-200": { light: "#d1c4a6", dark: "#d1c4a6" },
  "--dsw-static-neutral-bluish-300": { light: "#c1b396", dark: "#c1b396" },
  "--dsw-static-neutral-bluish-310": { light: "#bba98d", dark: "#bba98d" },
  "--dsw-static-neutral-bluish-400": { light: "#a59576", dark: "#a59576" },
  "--dsw-static-neutral-bluish-500": { light: "#8b7c60", dark: "#8b7c60" },
  "--dsw-static-neutral-bluish-600": { light: "#73654e", dark: "#73654e" },
  "--dsw-static-neutral-bluish-700": { light: "#594e3a", dark: "#594e3a" },
  "--dsw-static-neutral-bluish-750": { light: "#433c2c", dark: "#433c2c" },
  "--dsw-static-neutral-bluish-800": { light: "#363021", dark: "#363021" },
  "--dsw-static-neutral-bluish-850": { light: "#2a251a", dark: "#2a251a" },
  "--dsw-static-neutral-bluish-875": { light: "#231e15", dark: "#231e15" },
  "--dsw-static-neutral-bluish-900": { light: "#1c1812", dark: "#1c1812" },
  "--dsw-static-neutral-bluish-950": { light: "#16130e", dark: "#16130e" },
  "--dsw-static-neutral-bluish-1000": { light: "#110f0a", dark: "#110f0a" },
  "--dsw-static-neutral-50": { light: "#f0e7d1", dark: "#f0e7d1" },
  "--dsw-static-neutral-100": { light: "#e6dcc5", dark: "#e6dcc5" },
  "--dsw-static-neutral-150": { light: "#d9cdb2", dark: "#d9cdb2" },
  "--dsw-static-neutral-200": { light: "#cfc2a3", dark: "#cfc2a3" },
  "--dsw-static-neutral-250": { light: "#c6b898", dark: "#c6b898" },
  "--dsw-static-neutral-300": { light: "#c1b396", dark: "#c1b396" },
  "--dsw-static-neutral-400": { light: "#a59576", dark: "#a59576" },
  "--dsw-static-neutral-500": { light: "#8b7c60", dark: "#8b7c60" },
  "--dsw-static-neutral-550": { light: "#73654e", dark: "#73654e" },
  "--dsw-static-neutral-600": { light: "#6a5d47", dark: "#6a5d47" },
  "--dsw-static-neutral-700": { light: "#594e3a", dark: "#594e3a" },
  "--dsw-static-neutral-800": { light: "#363021", dark: "#363021" },
  "--dsw-static-neutral-850": { light: "#2a251a", dark: "#2a251a" },
  "--dsw-static-neutral-900": { light: "#1c1812", dark: "#1c1812" },
  "--dsw-static-neutral-1000": { light: "#110f0a", dark: "#110f0a" },
  "--dsw-static-deepseek-50": { light: "#ecdfc4", dark: "#ecdfc4" },
  "--dsw-static-deepseek-100": { light: "#e5d4b3", dark: "#e5d4b3" },
  "--dsw-static-deepseek-200": { light: "#dcc9a4", dark: "#dcc9a4" },
  "--dsw-alias-border-l1": { light: "#241c0f0a", dark: "#f5ead80f" },
  "--dsw-alias-border-l2-darkmode-thin": { light: "#241c0f1a", dark: "#f5ead80f" },
  "--dsw-alias-border-l2": { light: "#241c0f1a", dark: "#f5ead81f" },
  "--dsw-alias-border-l3": { light: "#241c0f1f", dark: "#f5ead829" },
  "--dsw-alias-border-l4": { light: "#241c0f29", dark: "#f5ead833" },
  "--dsw-alias-bg-skeleton": { light: "#241c0f0a", dark: "#f5ead814" },
  "--dsw-alias-bg-mask-drop": { light: "#f6efddb3", dark: "#231e15b3" },
  "--dsw-menu-surface-fill": { light: "#f6efddb3", dark: "#231e15a3" },
  "--dsw-alias-menu-group-header-fill": { light: "#f6efddf0", dark: "#231e15f0" },
  "--dsw-specific-menu": { light: "#f6efddb3", dark: "#231e15a3" },
  "--dsw-alias-interactive-bg-hover": { light: "#241c0f0f", dark: "#f5ead814" },
  "--dsw-alias-interactive-bg-hover-accent": { light: "#241c0f24", dark: "#f5ead83d" },
  "--dsw-alias-interactive-bg-active": { light: "#241c0f1a", dark: "#f5ead824" },
  "--dsw-alias-button-tool-bar-fill": { light: "#3a322580", dark: "#3a322580" },
  "--dsw-alias-button-tool-bar-hover": { light: "#3a322599", dark: "#3a322599" },
  "--dsw-alias-button-tool-bar-fill-invisible": { light: "#241c0f5c", dark: "#241c0f5c" },
  "--dsw-alias-bg-document-selection": { light: "color-mix(in srgb, var(--dsw-static-amber-500) 40%, transparent)", dark: "color-mix(in srgb, var(--dsw-static-amber-500) 40%, transparent)" },
};

function grainStyle(tag) {
  tag.dataset.plugin = '@local/dsh-dabaitu';
  tag.dataset.pluginCss = 'paper-grain';
  tag.textContent = [
    'html{background-color:var(--dsw-alias-bg-base)}',
    'html::after{',
    'content:"";position:fixed;inset:0;z-index:2147483647;pointer-events:none;',
    'background-image:url("' + PAPER_GRAIN + '");',
    'background-repeat:repeat;background-size:256px 256px;',
    'opacity:.45;mix-blend-mode:multiply',
    '}',
  ].join('');
}

// 标题栏那个文字按钮的样子：与宿主自带的标题控件同一套排版（13px、圆角、hover 换底色），
// 颜色全部走别名 token，所以它自己也跟着纸配色走。
function actionStyle(tag) {
  tag.dataset.plugin = '@local/dsh-dabaitu';
  tag.dataset.pluginCss = 'header-action';
  tag.textContent = [
    '.dabaitu-header-action{',
    '-webkit-app-region:no-drag;appearance:none;border:0;background:transparent;',
    'display:inline-flex;align-items:center;gap:4px;min-height:24px;padding:0 8px;',
    'border-radius:var(--dsw-radius-sm,6px);font:inherit;font-size:13px;font-weight:500;',
    'line-height:20px;white-space:nowrap;cursor:pointer;',
    'color:var(--dsw-alias-label-secondary);transition:background .12s,color .12s',
    '}',
    '@media (hover:hover){.dabaitu-header-action:hover{',
    'background:var(--dsw-alias-interactive-bg-hover);color:var(--dsw-alias-label-primary)}}',
    '.dabaitu-header-action:focus-visible{outline:2px solid var(--dsw-alias-border-l3);outline-offset:2px}',
  ].join('');
}

window.__ModuleLoader__.load({
  id: '@local/dsh-dabaitu',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    // 肉包吉祥物：已从贴图中抠出（去掉白底与「肉包」字样），128x76 PNG，内联为 data URI。
    function BunMark({ size }) {
      const side = typeof size === 'number' && size > 0 ? size : 24;
      return h('span', {
        'aria-hidden': 'true',
        style: {
          display: 'inline-flex', width: side, height: side, flex: 'none',
          alignItems: 'center', justifyContent: 'center',
        },
      }, h('img', {
        src: MARK_SRC, alt: '', draggable: false, loading: 'eager',
        style: {
          display: 'block', maxWidth: '100%', maxHeight: '100%', objectFit: 'contain',
          filter: 'drop-shadow(0 1px 2px rgba(0,0,0,.45))',
        },
      }));
    }

    function BunName() {
      // 与外壳回退标签同一套排版（17px、不换行），保持品牌行的视觉一致。
      return h('span', {
        style: { letterSpacing: 0, whiteSpace: 'nowrap', fontSize: '17px' },
      }, NAME_TEXT);
    }

    // 「豆包」按钮：在应用内右侧的 Browser tab 里打开 doubao.com。
    // 先走 ISidebarRight 的 openTab（它用的就是当前会话，也就是这张标题栏所属的会话）；
    // 万一它抛错（没有当前会话、browser 这一类 tab 没注册），退到 openTabIn，再退到系统浏览器。
    function makeDoubaoAction(ctx) {
      const openOptions = { params: { url: DOUBAO_URL } };
      const openDoubao = (sessionId) => {
        const right = ctx.get('sidebarRight');
        const tabs = ctx.get('sidebarRightTabs');
        if (right !== undefined && (tabs === undefined || tabs.get('browser') !== undefined)) {
          try {
            right.openTab('browser', openOptions);
            return;
          } catch {}
          if (typeof sessionId === 'string') {
            try {
              right.openTabIn(sessionId, 'browser', openOptions);
              return;
            } catch {}
          }
        }
        window.open(DOUBAO_URL, '_blank', 'noopener,noreferrer');
      };
      return function DoubaoAction({ sessionId }) {
        return h('button', {
          type: 'button',
          className: 'dabaitu-header-action',
          title: '在应用内打开 ' + DOUBAO_URL,
          onClick: () => openDoubao(sessionId),
        }, DOUBAO_TEXT);
      };
    }

    return {
      inject: ['slots', 'theme'],
      apply(ctx) {
        // 1) 品牌：等侧栏声明出现再注册，声明消失一并撤回。
        //    这两个槽位是 kind:'single' 的 root 槽位，宿主槽位目录里它们的
        //    registerOptions 是空的——照官方填充（dsh-client-ui-brand-official）与
        //    LiveShare 的写法只给 name，不塞 id/key/label 这类不被接受的选项。
        ctx.slots.inject('sidebar.brand.mark', () => ctx.slots.inject('sidebar.brand.name', function* () {
          yield ctx.slots.register({ name: 'sidebar.brand.mark' }, BunMark);
          yield ctx.slots.register({ name: 'sidebar.brand.name' }, BunName);
        }));

        // 2) 调色：一层 token 覆盖，卸载时宿主自动撤销。
        ctx.theme.overrideTokens('paper', PAPER_TOKENS);

        // 3) 纸纹叠加层（effect 的清理函数跟着插件 fiber 走）。
        ctx.effect(() => {
          const tag = document.createElement('style');
          grainStyle(tag);
          document.head.append(tag);
          return () => tag.remove();
        }, '@local/dsh-dabaitu: paper grain overlay');

        // 4) 标题栏「豆包」：conversation.session.header.actions 是 kind:'list' 的
        //    session 槽位（由 ui-conversation 的 conversation.session.header 填充声明），
        //    宿主目录里它的 registerOptions 是「id 必填，order/label 可选」，条目按 order
        //    升序排在标题右边。自带的几档是 agent-team -20 / agent-preset -10 /
        //    subagent-catalog 10 / job-list 20，所以 -30 正好落在标题正后方。
        const DoubaoAction = makeDoubaoAction(ctx);
        ctx.slots.inject('conversation.session.header.actions', () => ctx.slots.register({
          name: 'conversation.session.header.actions',
          id: 'dabaitu-doubao',
          order: -30,
          label: DOUBAO_TEXT,
        }, DoubaoAction));

        ctx.effect(() => {
          const tag = document.createElement('style');
          actionStyle(tag);
          document.head.append(tag);
          return () => tag.remove();
        }, '@local/dsh-dabaitu: header action style');
      },
    };
  },
});
